    63  #if defined(HAVE_SPLASH)
    64  bool page_renderer_private::conv_color_mode(image::format_enum mode,
    65                                              SplashColorMode &splash_mode)
    66  {
    67      switch (mode) {
    68          case image::format_enum::format_mono:
    69              splash_mode = splashModeMono1;
    70              break;
    71          case image::format_enum::format_gray8:
    72              splash_mode = splashModeMono8;
    73              break;
    74          case image::format_enum::format_rgb24:
    75              splash_mode = splashModeRGB8;
    76              break;
    77          case image::format_enum::format_bgr24:
    78              splash_mode = splashModeBGR8;
    79              break;
    80          case image::format_enum::format_argb32:
    81              splash_mode = splashModeXBGR8;
    82              break;
    83          default:
    84              return false;
    85      }
    86      return true;
    87  }
