    89  bool page_renderer_private::conv_line_mode(page_renderer::line_mode_enum mode,
    90                                             SplashThinLineMode &splash_mode)
    91  {
    92      switch (mode) {
    93          case page_renderer::line_mode_enum::line_default:
    94              splash_mode = splashThinLineDefault;
    95              break;
    96          case page_renderer::line_mode_enum::line_solid:
    97              splash_mode = splashThinLineSolid;
    98              break;
    99          case page_renderer::line_mode_enum::line_shape:
   100              splash_mode = splashThinLineShape;
   101              break;
   102          default:
   103              return false;
   104      }
   105      return true;
   106  }
   107  #endif
